function escapeCSVString(str) {
  // 如果字符串中包含逗号或双引号，则将其用双引号括起来，并且内部的双引号需要转义
  if (str.includes(',') || str.includes('"')) {
    return '"' + str.replace(/"/g, '""').replace(/\n/g, '\\n').replace(/\r/g, '\\r')+ '"';
  }
  return str;
}


