function parseCsvLine(line) {
  const columns = [];
  let currentColumn = '';
  let isInQuotes = false;

  for (let i = 0; i < line.length; i++)
  {
    const char = line[i];

    if (char === '"') {
      isInQuotes = !isInQuotes;
    } 
    else if (char === ',' && !isInQuotes) {
      columns.push(currentColumn);
      currentColumn = '';
    } 
    else {
      currentColumn += char;
    }
  }

  columns.push(currentColumn); // 添加最后一列

  return columns;
}




